mapper.select:
select warehouse_id
from `ry_rental`.`ry_rental_user_warehouse_scope`
where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and merchant_user_id = #{merchantUserId}
order by warehouse_id

mapper.delete:
delete from `ry_rental`.`ry_rental_user_warehouse_scope`
where tenant_id = #{tenantId}
  and member_id = #{memberId}
  and merchant_user_id = #{merchantUserId}
